ee:message.ee:set-payload:
%dw 2.0
output application/java
var orders = {
  "TW-1001": { orderId: "TW-1001", customer: { name: "Ana Souza",  email: "ana.souza@example.com" },
               items: [{ sku: "TW-KB-75",  description: "Teclado mecanico 75%", qty: 1, unitPrice: 89.90 }],
               status: "DELIVERED", paymentIntentId: "pi_REPLACE_WITH_YOUR_TEST_PAYMENT_INTENT" },
  "TW-1002": { orderId: "TW-1002", customer: { name: "Bruno Lima", email: "bruno.lima@example.com" },
               items: [{ sku: "TW-MN-27",  description: "Monitor 27in 144Hz",   qty: 1, unitPrice: 379.00 }],
               status: "SHIPPED",   paymentIntentId: "pi_REPLACE_WITH_YOUR_TEST_PAYMENT_INTENT" },
  "TW-1003": { orderId: "TW-1003", customer: { name: "Carla Dias", email: "carla.dias@example.com" },
               items: [{ sku: "TW-HS-X1",  description: "Headset USB-C",        qty: 2, unitPrice: 59.50 }],
               status: "PROCESSING", paymentIntentId: "pi_REPLACE_WITH_YOUR_TEST_PAYMENT_INTENT" },
  // Pedido de reserva para o caminho feliz do reembolso: o PaymentIntent do
  // TW-1002 ja foi reembolsado, e o Stripe recusa um segundo com
  // `charge_already_refunded`. Este aqui tem pagamento succeeded e intacto —
  // e o valor (R$ 100,00) bate com os 10000 centavos do PaymentIntent.
  "TW-1004": { orderId: "TW-1004", customer: { name: "Diego Nunes", email: "diego.nunes@example.com" },
               items: [{ sku: "TW-MS-PRO", description: "Mouse sem fio Pro",    qty: 1, unitPrice: 100.00 }],
               status: "SHIPPED",   paymentIntentId: "pi_REPLACE_WITH_YOUR_TEST_PAYMENT_INTENT" }
}
---
orders[vars.orderId]

logger.message:
#[output application/json --- {message: 'Stripe PaymentIntent response', tracePoint: 'AFTER_REQUEST'} ++ ({
            paymentStatus: vars.stripePayment.status default 'unknown',
            amount: vars.stripePayment.amount default 0
          })]

ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
  orderId: vars.order.orderId,
  status: vars.order.status,
  customer: vars.order.customer,
  items: vars.order.items,
  payment: {
    paymentIntentId: vars.order.paymentIntentId,
    status: vars.stripePayment.status,
    amount: (vars.stripePayment.amount default 0) / 100,
    currency: upper(vars.stripePayment.currency default "usd"),
    // `amount_refunded > 0` entra no OR de proposito: pega reembolso PARCIAL,
    // que deixa `refunded` em false. Para um guardrail de "nao reembolse de
    // novo", qualquer valor ja devolvido tem que contar.
    refunded: ((vars.stripePayment.latest_charge.refunded default false) == true)
      or ((vars.stripePayment.latest_charge.amount_refunded default 0) > 0)
  }
}

logger.message:
#[output application/json --- {message: 'Order lookup failed: ' ++ error.description, tracePoint: 'EXCEPTION'} ++ ({
            orderId: vars.orderId default 'unknown',
            errorType: error.errorType.identifier default 'UNKNOWN',
            errorDescription: error.description
          })]
